<template><div class="app-container"><el-alert title="会议通知独立于系统公告。重要/紧急通知可配置公开范围和有效期，用户阅读会留下已读记录。" type="info" :closable="false" class="mb16"/><el-button type="primary" plain class="mb12" @click="add">新增通知</el-button><el-table :data="rows" v-loading="loading"><el-table-column prop="title" label="标题"/><el-table-column prop="priority" label="优先级" width="100"/><el-table-column prop="visibility" label="可见范围" width="110"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="publishTime" label="发布时间" width="180"/><el-table-column label="操作" width="100"><template #default="scope"><el-button link type="primary" @click="edit(scope.row)">编辑</el-button></template></el-table-column></el-table><el-dialog v-model="open" :title="form.noticeId?'编辑通知':'新增通知'" width="850px" append-to-body><el-form :model="form" label-width="90px"><el-form-item label="标题"><el-input v-model="form.title"/></el-form-item><el-row :gutter="16"><el-col :span="8"><el-form-item label="优先级"><el-select v-model="form.priority"><el-option label="普通" value="normal"/><el-option label="重要" value="important"/><el-option label="紧急" value="urgent"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="可见范围"><el-select v-model="form.visibility"><el-option label="公开" value="public"/><el-option label="登录可见" value="login"/><el-option label="报名后可见" value="registered"/></el-select></el-form-item></el-col><el-col :span="8"><el-form-item label="状态"><el-select v-model="form.status"><el-option label="草稿" value="draft"/><el-option label="发布" value="published"/><el-option label="归档" value="archived"/></el-select></el-form-item></el-col></el-row><el-form-item label="正文"><editor v-model="form.contentHtml" :min-height="300"/></el-form-item></el-form><template #footer><el-button type="primary" @click="save">保存</el-button><el-button @click="open=false">取消</el-button></template></el-dialog></div></template>
<script setup name="MeetingNotice">import{computed,getCurrentInstance,onMounted,ref}from'vue';import{useRoute}from'vue-router';import{listMeetingNotices,saveMeetingNotice}from'@/api/meeting/notice';const{proxy}=getCurrentInstance(),route=useRoute(),activityId=computed(()=>Number(route.query.id)),rows=ref([]),loading=ref(false),open=ref(false),form=ref({});function getList(){loading.value=true;listMeetingNotices({activityId:activityId.value,pageNum:1,pageSize:100}).then(r=>rows.value=r.rows||[]).finally(()=>loading.value=false)}function add(){form.value={activityId:activityId.value,title:'',contentHtml:'',priority:'normal',visibility:'public',status:'draft'};open.value=true}function edit(row){form.value={...row};open.value=true}function save(){saveMeetingNotice(form.value).then(()=>{proxy.$modal.msgSuccess('保存成功');open.value=false;getList()})}onMounted(getList)</script>
